={{ 
(() => {
  const rawText = $json.output[0].content[0].text;

  // 1. IMPROVED TITLE EXTRACTION
  // This looks specifically for the text following "TITLE:" or the first non-empty line
  const titleMatch = rawText.match(/TITLE:\s*\n*(.*)/i);
  const mainTitle = titleMatch ? titleMatch[1].trim() : rawText.split('\n')[0].trim();

  // 2. PROCESS BODY CONTENT
  let cleanBody = rawText
    .replace(/TITLE:.*\n?/i, '') // Remove the "TITLE:" label and its line
    .replace(new RegExp(mainTitle, 'i'), '') // Remove the duplicate title from the body
    .replace(/INTRO:\s*\n?/gi, '') // Remove INTRO label

    // REDUCED SPACING FOR SECTION TITLES:
    // We set margin-bottom to 0px to pull the content up
    .replace(/SECTION \d+ TITLE:\s*\n?(.*)/gi, '<h2 style="color: #2e7d32; font-size: 20px; border-bottom: 2px solid #e8f5e9; padding-bottom: 5px; margin-top: 25px; margin-bottom: 0px;">$1</h2>') 

    // REDUCED SPACING FOR CONTENT:
    // We use a specific paragraph style with a tiny margin-top (4px) to tighten the gap
    .replace(/SECTION \d+ CONTENT:\s*\n?/gi, '<p style="margin-top: 4px; margin-bottom: 15px;">')
    .replace(/(SECTION \d+:|SECTION \d+)/gi, '') // Cleanup any remaining section numbers

    .replace(/CONCLUSION:/gi, '<h2 style="color: #2e7d32; font-size: 20px; border-bottom: 2px solid #e8f5e9; padding-bottom: 5px; margin-top: 25px; margin-bottom: 0px;"></h2>') 
    .replace(/CTA:/gi, '<br><div style="background:#e8f5e9;padding:15px;border-radius:8px;border-left:5px solid #2e7d32;"><strong>')
    .replace(/\n\n+/g, '</p><p style="margin-bottom: 15px;">') 
    .replace(/\n/g, '<br>');

  // 3. HTML CONTAINER
  return `
<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; border: 1px solid #ddd; border-radius: 8px; overflow: hidden;">
  <div style="background-color: #2e7d32; padding: 40px 20px; text-align: center;">
    <h1 style="color: #ffffff; margin: 0; font-size: 26px; font-weight: bold; text-transform: uppercase;">${mainTitle}</h1>
  </div>
  <div style="padding: 25px;">
    <p>${cleanBody}</strong></div>
  </div>
  <div style="background: #f4f4f4; padding: 15px; text-align: center; font-size: 11px; color: #777; letter-spacing: 1px;">
    © 2026 SAVE EARTH INITIATIVE
  </div>
</div>`;
})()
}}
